corrected_code:
@login_required
@require_POST
def delete_shipping_address(request):
    address_id = request.POST.get('address_id')
    deleted_count, _ = DeliveryAddress.objects.filter(id=address_id, customer=request.user).delete()
    if not deleted_count:
        raise PermissionDenied("Address not found or unauthorized.")
    messages.info(request, "Delivery address removed.")
    return redirect('customer_addresses')
